// Clincoo Blog bundle extra 2026-10-01
(function(){
  var extra = [
    {id:'bundle-ukur-ukuran-sebelum-tambah-pustaka',langs:{id:{title:'Ukur Ukuran Bundle Clincoo sebelum Menambah Pustaka',desc:'Satu dependensi baru bisa menambah puluhan kilobyte. Cek budget bundle di pratinjau sebelum import.',content:'<p class=\"mb-4\">Import di editor.clincoo.buzz sering terasa murah sampai Lighthouse menunjuk JavaScript yang tidak terpakai.</p><p class=\"mb-4\">Catat ukuran transfer halaman sebelum dan sesudah menambah pustaka. Tolak perubahan jika budget terlampaui tanpa alasan.</p><p class=\"mb-4\">Pilih fungsi sempit, bukan SDK utuh. Tree-shake hanya bekerja jika import spesifik.</p><p class=\"mb-4\">Tempel laporan ukuran ke AI dan minta alternatif lebih kecil. Jangan minta menelan bundler baru di commit yang sama.</p><p class=\"mb-4\">Simpan angka budget di README proyek app.clincoo.buzz dan tautkan contoh di blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Measure the Clincoo Bundle Size before Adding a Library',desc:'One new dependency can add tens of kilobytes. Check the bundle budget in preview before you import.',content:'<p class=\"mb-4\">An import on editor.clincoo.buzz often feels cheap until Lighthouse points at unused JavaScript.</p><p class=\"mb-4\">Record the page transfer size before and after adding the library. Reject the change if the budget is blown without a reason.</p><p class=\"mb-4\">Pick a narrow function, not a full SDK. Tree-shaking only works with a specific import.</p><p class=\"mb-4\">Paste the size report to AI and ask for a smaller alternative. Do not request a new bundler in the same commit.</p><p class=\"mb-4\">Store the budget number in the app.clincoo.buzz project README and link an example on blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}},
    {id:'bundle-pisah-vendor-dari-kode-app',langs:{id:{title:'Pisahkan Chunk Vendor dari Kode Aplikasi Clincoo',desc:'Pisah vendor agar cache browser tidak pecah setiap kali Anda menyimpan draf di editor.',content:'<p class=\"mb-4\">Jika vendor dan kode halaman Clincoo berada di satu file, setiap huruf yang diubah di editor.clincoo.buzz memaksa pengunjung mengunduh ulang pustaka besar.</p><p class=\"mb-4\">Minta bundler mengekstrak node_modules ke chunk vendor. Hash vendor hanya berubah saat lockfile berubah.</p><p class=\"mb-4\">Uji di pratinjau: hard refresh sekali, lalu muat ulang biasa. Network harus menandai vendor dari disk cache.</p><p class=\"mb-4\">Jangan campur polyfill langka ke vendor utama. Dynamic import polyfill hanya untuk browser yang membutuhkannya.</p><p class=\"mb-4\">Catat nama chunk di README app.clincoo.buzz supaya AI tidak menggabungkan semuanya lagi saat diminta merapikan config.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Split the Vendor Chunk from Clincoo App Code',desc:'Keep vendor separate so the browser cache does not break every time you save a draft in the editor.',content:'<p class=\"mb-4\">If vendor and Clincoo page code live in one file, every letter you change on editor.clincoo.buzz forces visitors to re-download a large library.</p><p class=\"mb-4\">Ask the bundler to extract node_modules into a vendor chunk. The vendor hash should change only when the lockfile changes.</p><p class=\"mb-4\">Test in preview: hard refresh once, then a normal reload. Network should mark vendor as served from disk cache.</p><p class=\"mb-4\">Do not dump rare polyfills into the main vendor file. Dynamic-import a polyfill only for browsers that need it.</p><p class=\"mb-4\">Record chunk names in the app.clincoo.buzz README so AI does not merge them again when asked to tidy the config.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}},
    {id:'bundle-dynamic-import-halaman-jarang',langs:{id:{title:'Pakai Dynamic Import untuk Halaman Clincoo yang Jarang Dibuka',desc:'Jangan masukkan wizard, modal berat, atau panel admin ke bundle beranda.',content:'<p class=\"mb-4\">Beranda app.clincoo.buzz tidak perlu membawa editor markdown atau pemilih ikon sampai pengguna membukanya.</p><p class=\"mb-4\">Ganti import statis dengan import() di event klik atau rute. Pastikan ada fallback loading yang singkat.</p><p class=\"mb-4\">Cek tab Coverage di DevTools setelah pratinjau. Byte yang tetap abu-abu adalah kandidat pecah chunk.</p><p class=\"mb-4\">Tempel coverage ke AI dan minta daftar modul yang aman di-lazy-load. Tolak saran yang memindahkan CSS kritis ke chunk lambat.</p><p class=\"mb-4\">Ukur LCP sebelum dan sesudah. Simpan angka di catatan rilis blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Use Dynamic Import for Rare Clincoo Screens',desc:'Do not ship the wizard, a heavy modal, or the admin panel inside the home bundle.',content:'<p class=\"mb-4\">The app.clincoo.buzz home page does not need a markdown editor or an icon picker until the user opens them.</p><p class=\"mb-4\">Replace a static import with import() on a click or a route. Keep a short loading fallback.</p><p class=\"mb-4\">Check the Coverage tab in DevTools after preview. Bytes that stay gray are candidates for a split chunk.</p><p class=\"mb-4\">Paste coverage into AI and ask which modules are safe to lazy-load. Reject advice that moves critical CSS into a late chunk.</p><p class=\"mb-4\">Measure LCP before and after. Store the numbers in the release note on blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}},
    {id:'bundle-cek-modul-ganda-di-devtools',langs:{id:{title:'Cek Modul Ganda di Bundle Clincoo lewat DevTools',desc:'Dua salinan lodash atau runtime yang sama merusak budget tanpa terlihat di source.',content:'<p class=\"mb-4\">Buka pratinjau editor.clincoo.buzz, tab Network, filter JS. Urutkan menurut ukuran. Nama chunk yang mencurigakan sering menyimpan duplikat.</p><p class=\"mb-4\">Gunakan visualizer bundler atau pencarian string versi pustaka di file hasil build. Dua versi React atau date library adalah alarm.</p><p class=\"mb-4\">Perbaiki lewat resolusi tunggal di package manager, bukan dengan menghapus fitur secara acak.</p><p class=\"mb-4\">Kirim output duplikat ke AI beserta lockfile singkat. Minta satu perintah perbaikan, bukan rewrite seluruh config.</p><p class=\"mb-4\">Ulangi ukur transfer di app.clincoo.buzz setelah lockfile terkunci.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Find Duplicate Modules in the Clincoo Bundle with DevTools',desc:'Two copies of lodash or the same runtime blow the budget without showing up in source.',content:'<p class=\"mb-4\">Open the editor.clincoo.buzz preview, Network tab, filter JS. Sort by size. A suspicious chunk name often hides a duplicate.</p><p class=\"mb-4\">Use a bundler visualizer or search the built file for a library version string. Two Reacts or two date libraries is an alarm.</p><p class=\"mb-4\">Fix it with a single resolution in the package manager, not by deleting features at random.</p><p class=\"mb-4\">Send the duplicate report to AI with a short lockfile excerpt. Ask for one fix command, not a full config rewrite.</p><p class=\"mb-4\">Measure transfer again on app.clincoo.buzz after the lockfile is pinned.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}},
    {id:'bundle-jangan-kirim-sourcemap-produksi',langs:{id:{title:'Jangan Kirim Source Map ke Produksi Bundle Clincoo',desc:'File .map membocorkan source dan menambah megabyte pada unduhan pertama.',content:'<p class=\"mb-4\">Source map berguna di pratinjau editor.clincoo.buzz, bukan di domain publik app.clincoo.buzz.</p><p class=\"mb-4\">Matikan generation map untuk build produksi atau unggah map ke penyimpanan privat yang hanya dibuka saat debug.</p><p class=\"mb-4\">Cek Network: jika ada permintaan .map 200 dari pengunjung anonim, anggap itu kebocoran.</p><p class=\"mb-4\">Jangan minta AI mengaktifkan source map agar error produksi terlihat lebih cantik. Minta logging terstruktur saja.</p><p class=\"mb-4\">Dokumentasikan kebijakan map di blog.clincoo.buzz supaya anggota tim tidak menghidupkannya lagi saat panik.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Do Not Ship Source Maps with the Production Clincoo Bundle',desc:'.map files leak source and add megabytes to the first download.',content:'<p class=\"mb-4\">Source maps help in the editor.clincoo.buzz preview, not on the public app.clincoo.buzz domain.</p><p class=\"mb-4\">Turn off map generation for the production build or upload maps to private storage that opens only during debug.</p><p class=\"mb-4\">Check Network: a 200 for a .map from an anonymous visitor is a leak.</p><p class=\"mb-4\">Do not ask AI to enable source maps so production errors look prettier. Ask for structured logging instead.</p><p class=\"mb-4\">Document the map policy on blog.clincoo.buzz so the team does not turn them back on during a panic.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}},
    {id:'bundle-tunda-skrip-pihak-ketiga',langs:{id:{title:'Tunda Skrip Pihak Ketiga agar Bundle Clincoo Tetap Ringan',desc:'Analitik, chat, dan pixel jangan menempel di entry utama halaman.',content:'<p class=\"mb-4\">Skrip pihak ketiga sering lebih berat daripada kode yang Anda tulis di editor.clincoo.buzz.</p><p class=\"mb-4\">Muat mereka setelah idle atau setelah interaksi pertama. Pakai async atau dynamic import, bukan tag sinkron di head.</p><p class=\"mb-4\">Blokir skrip di pratinjau sekali untuk melihat LCP tanpa noise vendor. Bandingkan angka sebelum mengaktifkan kembali.</p><p class=\"mb-4\">Jika AI menyarankan SDK lengkap untuk satu event pageview, minta snippet pixel polos sebagai gantinya.</p><p class=\"mb-4\">Simpan daftar skrip yang diizinkan di README app.clincoo.buzz dan tautkan audit di blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Defer Third-Party Scripts so the Clincoo Bundle Stays Lean',desc:'Analytics, chat, and pixels should not cling to the page entry file.',content:'<p class=\"mb-4\">Third-party scripts are often heavier than the code you write in editor.clincoo.buzz.</p><p class=\"mb-4\">Load them after idle or after the first interaction. Use async or a dynamic import, not a sync tag in the head.</p><p class=\"mb-4\">Block the scripts once in preview to see LCP without vendor noise. Compare the numbers before you turn them back on.</p><p class=\"mb-4\">If AI suggests a full SDK for a single pageview event, ask for a plain pixel snippet instead.</p><p class=\"mb-4\">Keep an allow-list of scripts in the app.clincoo.buzz README and link the audit on blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}},
    {id:'bundle-buang-polyfill-yang-sudah-didukung',langs:{id:{title:'Buang Polyfill yang Browser Target Clincoo Sudah Dukung',desc:'core-js penuh sering masuk bundle hanya karena satu metode lama.',content:'<p class="mb-4">Buka treemap build pratinjau editor.clincoo.buzz dan cari folder core-js atau polyfill regenerator.</p><p class="mb-4">Cocokkan browserslist dengan fitur yang benar-benar Anda panggil. Promise dan fetch sudah ada di browser target modern.</p><p class="mb-4">Ganti impor polyfill global dengan satu helper kecil, atau hapus jika tidak terpanggil.</p><p class="mb-4">Minta AI menandai impor polyfill yang aman dihapus. Jangan biarkan AI menambah preset Babel baru.</p><p class="mb-4">Catat penghematan byte di catatan rilis app.clincoo.buzz dan tautkan di blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Drop Polyfills Already Supported by Clincoo Target Browsers',desc:'A full core-js build often enters the bundle because of one old method.',content:'<p class="mb-4">Open the preview build treemap for editor.clincoo.buzz and look for a core-js or regenerator polyfill folder.</p><p class="mb-4">Match browserslist to the features you actually call. Promise and fetch already exist in modern target browsers.</p><p class="mb-4">Replace a global polyfill import with one small helper, or remove it if nothing calls it.</p><p class="mb-4">Ask AI to mark polyfill imports that are safe to drop. Do not let AI add a new Babel preset.</p><p class="mb-4">Record the byte saving in the app.clincoo.buzz release note and link it on blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}}
  ];
  function merge(){
    if (!window.countryDataFiles || !window.countryDataFiles['bundle']) { setTimeout(merge, 30); return; }
    var arr = window.countryDataFiles['bundle'].articles;
    var have = {};
    for (var i = 0; i < arr.length; i++) have[arr[i].id] = true;
    for (var j = 0; j < extra.length; j++) { if (!have[extra[j].id]) arr.push(extra[j]); }
  }
  merge();
})();
